package com.lolfm.simulator;import static org.assertj.core.api.Assertions.*;import com.lolfm.factory.DummyDataFactory;import org.junit.jupiter.api.Test;class ProgressionReproducibilityTest{private MatchSimulator sim(){return new MatchSimulator(new TeamfightResolver(),new EndGameEvaluator(),new SnapshotFactory(),new ObjectiveResolver(),new PostFightResolver(),new ObjectiveAttemptResolver(),new StructureResolver(),new PushResolver(),SimulationOptions.productionDefaults());}@Test void sameSeedProducesSameCompleteResponse(){var f=new DummyDataFactory();var a=sim().simulate(f.createBlueTeam(),f.createRedTeam(),77);f=new DummyDataFactory();var b=sim().simulate(f.createBlueTeam(),f.createRedTeam(),77);assertThat(a).usingRecursiveComparison().isEqualTo(b);}@Test void directRewardsUseNoRandom(){var p=new PlayerState("p",com.lolfm.domain.Position.TOP,500);p.configureProgression(TeamSide.BLUE,true,new ProgressionExecutionStats());p.getProgressionState().awardExperience(ExperienceSource.KILL,180,1);p.addGold(300,GoldSource.KILL,1);assertThat(p.getProgressionState().getTotalExperience()).isEqualTo(180);}}
